/**
 * Suite for computeCash + computeSavings (src/logic.ts) — the Bank Balance card
 * and the "Cash generated by month" drill behind it.
 *
 * Run: bash qa/run-tests.sh
 *
 * Fixtures are shaped after real production rows (D1 `spira`, read-only):
 *   expenses id 99  — 2026-05-01, Spira 3028, "Monthly rent",  ₹45,000, Recurring, init_invest=1
 *   expenses id 147 — 2026-08-06, Spira 2212, "August Rent",   ₹51,920, Recurring, init_invest=1
 * Every expected number below is derived by hand in the comment above it.
 * Assertions named [BUG] assert the CORRECT value and FAIL today — they are the
 * proof of a finding, not a regression.
 */
import { computeCash, computeSavings, LogBlock } from '../src/logic';

let pass = 0, fail = 0;
const failures: string[] = [];
function eq(name: string, got: any, want: any) {
  const g = JSON.stringify(got), w = JSON.stringify(want);
  if (g === w) { pass++; }
  else { fail++; failures.push(`✗ ${name}\n    got:  ${g}\n    want: ${w}`); }
}
const block = (rows: any[]): LogBlock => ({ headers: [], rows });

/* BOOKING_COLS: 0 date · 1 property · 3 type · 4 channel · 9 net_earned ·
   11 pending_amount · 18 booking_id */
let bn = 1;
function bk(o: { id?: string; date: string; prop: string; net: number; pend?: number }) {
  const c: any[] = new Array(27).fill('');
  c[0] = o.date; c[1] = o.prop; c[2] = 'Guest'; c[3] = 'Stay'; c[4] = 'Airbnb';
  c[9] = o.net; c[11] = o.pend === undefined ? '' : o.pend;
  c[18] = o.id === undefined ? 'B' + bn : o.id;
  return { r: bn++, cells: c };
}
/* EXPENSE_COLS: 0 txn_date · 1 expense_month · 2 item · 3 property · 4 category ·
   6 amount · 7 type · 12 init_invest */
let en = 1;
function ex(o: { txn: string; month: string; item: string; prop: string; amt: number; type: string; init?: any }) {
  const c: any[] = new Array(13).fill('');
  c[0] = o.txn; c[1] = o.month; c[2] = o.item; c[3] = o.prop; c[4] = 'Rent';
  c[6] = o.amt; c[7] = o.type; c[12] = o.init === undefined ? 0 : o.init;
  return { r: en++, cells: c };
}
/* SAVING_COLS: 0 date · 1 amount · 2 scheme · 3 platform · 4 status ·
   5 returns (TOTAL received on exit) · 8 exit_date */
let sn = 1;
function sv(o: { date: string; amt: number; status: string; ret?: number; exit?: string; scheme?: string; platform?: string }) {
  const c: any[] = new Array(9).fill('');
  c[0] = o.date; c[1] = o.amt; c[2] = o.scheme || 'FD'; c[3] = o.platform || 'HDFC';
  c[4] = o.status; c[5] = o.ret === undefined ? '' : o.ret; c[8] = o.exit || '';
  return { r: sn++, cells: c };
}

/* ══════════════════════════════════════════════════════════════════════════
   THE CORE FIXTURE
   Bookings                                         net     pending
     B1  2026-05-10  Spira 3028                   10,000         0
     B2  2026-05-20  Spira 2212                    6,000     2,000
     B3  2026-08-05  Spira 3028                    4,000         0
       Σ net = 20,000 · Σ pending(>0) = 2,000
   Expenses
     E1  2026-05-01  Spira 3028  Recurring  45,000  init_invest=1   (prod id 99 shape)
     E2  2026-05-03  Spira 3028  Recurring   5,000  init_invest=0
     E3  2026-08-06  Spira 2212  Operating   1,000  init_invest=0
     E4  2026-05-05  Spira 3028  One-time    9,000  init_invest=0   (paid from business cash → bank only)
   Savings
     S1  2026-05-15  ₹3,000  Active
     S2  2026-06-01  ₹1,000  Matured 2026-06-20, received ₹1,200 (gain ₹200)
   ══════════════════════════════════════════════════════════════════════════ */
function fixture() {
  bn = 1; en = 1; sn = 1;
  const B = block([
    bk({ date: '2026-05-10', prop: 'Spira 3028', net: 10000 }),
    bk({ date: '2026-05-20', prop: 'Spira 2212', net: 6000, pend: 2000 }),
    bk({ date: '2026-08-05', prop: 'Spira 3028', net: 4000 }),
  ]);
  const E = block([
    ex({ txn: '2026-05-01', month: '2026-05-01', item: 'Monthly rent', prop: 'Spira 3028', amt: 45000, type: 'Recurring', init: 1 }),
    ex({ txn: '2026-05-03', month: '2026-05-01', item: 'Electricity',  prop: 'Spira 3028', amt: 5000,  type: 'Recurring', init: 0 }),
    ex({ txn: '2026-08-06', month: '2026-08-01', item: 'Cleaning',     prop: 'Spira 2212', amt: 1000,  type: 'Operating', init: 0 }),
    ex({ txn: '2026-05-05', month: '2026-05-01', item: 'Sofa',         prop: 'Spira 3028', amt: 9000,  type: 'One-time',  init: 0 }),
  ]);
  const S = block([
    sv({ date: '2026-05-15', amt: 3000, status: 'Active' }),
    sv({ date: '2026-06-01', amt: 1000, status: 'Matured', ret: 1200, exit: '2026-06-20' }),
  ]);
  return { B, E, S };
}

/* ── 1. The headline arithmetic, derived by hand ──────────────────────────
   totalNet = 10,000 + 6,000 + 4,000                       = 20,000
   pending  = 2,000 (only B2, and only because it is > 0)  =  2,000
   totalExp = 5,000 + 1,000  (E1 excluded: init_invest=1;
              E4 is not opex: One-time)                    =  6,000
   netPnL   = 20,000 − 6,000                               = 14,000
   oneTime  = 9,000 (E4: One-time, init_invest=0 → left the bank)
   svInvested = 3,000 (S1 Active) · svReturns = 1,200 − 1,000 = 200 (S2 gain)
   bank     = 14,000 − 2,000 − 9,000 − 3,000 + 200         =    200          */
{
  const { B, E, S } = fixture();
  const c = computeCash(B, E, 'All', S);
  eq('totalNet', c.totalNet, 20000);
  eq('pending', c.pending, 2000);
  eq('totalExp excludes initial-investment opex', c.totalExp, 6000);
  eq('netPnL', c.netPnL, 14000);
  eq('one-time spend not flagged initial investment', c.oneTime, 9000);
  eq('bank', c.bank, 200);
}

/* ── 2. FINDING: the Bank drill's total row does not add up ───────────────
   Dashboard.tsx:418-433 renders one table: a row per month with
   (Received, Opex, Cash), and a Total row of
     Received = totalNet − pending, Opex = totalExp, Cash = bank.
   By hand, month by month (computeCash lines 393 / 412):
     May 2026  recv = (10,000−0) + (6,000−2,000) = 14,000 · opex = 5,000 → cash  9,000
     Aug 2026  recv =  4,000−0                   =  4,000 · opex = 1,000 → cash  3,000
     Σ cash = 12,000
   The Total row prints Received 18,000, Opex 6,000, Cash 9,200.
   18,000 − 6,000 = 12,000 ≠ 9,200. The column sums to 12,000, the total says
   9,200, and the gap is exactly svInvested − svReturns = 2,800.
   Production magnitude (D1, today): Σnet 478,488.96 − pending 50,785 −
   totalExp 240,919 = 186,784.96 of monthly cash against a printed bank of
   87,646.96 — a visible ₹99,138 hole in a single table.                    */
{
  const { B, E, S } = fixture();
  const c = computeCash(B, E, 'All', S);
  eq('monthly rows', c.monthly, [
    { month: 'May 2026', recv: 14000, opex: 5000, oneTime: 9000, cash: 0 },
    { month: 'Aug 2026', recv: 4000, opex: 1000, oneTime: 0, cash: 3000 },
  ]);
  const sumCash = c.monthly.reduce((a, m) => a + m.cash, 0);
  eq('Σ monthly cash — current behaviour', sumCash, 3000);
  eq('Received − Opex − One-time equals Σ monthly cash', (c.totalNet - c.pending) - c.totalExp - c.oneTime, sumCash);
  /* The table's Cash column sums to bankBeforeSavings, which is what the total
     row prints (Dashboard.tsx). `bank` folds savings in on top and is shown on
     its own line, so the two are no longer conflated. */
  eq('the drill total row reconciles: Received − Opex − One-time = bankBeforeSavings', (c.totalNet - c.pending) - c.totalExp - c.oneTime, c.bankBeforeSavings);
  const dayTotal = Object.values(c.dayMap).reduce((a, v) => a + v, 0);
  eq('the daily bank curve ends on the bank balance', dayTotal, c.bank);
  eq('Σ monthly cash equals the printed total', sumCash, c.bankBeforeSavings);
  eq('bank is bankBeforeSavings adjusted by the savings leg', c.bankBeforeSavings - c.svInvested + c.svReturns, c.bank);

}

/* ── 3. FINDING: per-property banks do not sum to the All bank ────────────
   computeCash only applies savings when filter === 'All' (line 420), so:
     Spira 3028: net 14,000 · pending 0 · opex 5,000 (E1 still excluded)
                 netPnL 9,000 → bank 9,000
     Spira 2212: net  6,000 · pending 2,000 · opex 1,000
                 netPnL 5,000 → bank 3,000
     9,000 + 3,000 = 12,000, but the All view shows 9,200.
   Two properties are the whole business; a user who flips the filter across
   both and adds them up is 2,800 out (₹99,138 out in production). The gap is
   never shown on a per-property view — the "Savings adjustments" block in the
   drill is rendered only when filter === 'All' (Dashboard.tsx:437).          */
{
  const { B, E, S } = fixture();
  const all = computeCash(B, E, 'All', S);
  const p1 = computeCash(B, E, 'Spira 3028', S);
  const p2 = computeCash(B, E, 'Spira 2212', S);
  eq('Spira 3028 bank (E4 one-time leaves its bank)', p1.bank, 0);
  eq('Spira 2212 bank', p2.bank, 3000);
  eq('per-property banks sum', p1.bank + p2.bank, 3000);
  /* Savings are global, never per-property, so the per-property banks sum to the
     All view's bank BEFORE savings — and the difference is exactly the savings
     leg, not an unexplained gap. */
  eq('per-property banks sum to the All-view bank before savings', p1.bank + p2.bank, all.bankBeforeSavings);
  eq('the difference is exactly the savings leg', all.bankBeforeSavings - all.bank, all.svInvested - all.svReturns);
  eq('per-property views carry no savings leg', [p1.svInvested, p1.svReturns, p2.svInvested, p2.svReturns], [0, 0, 0, 0]);
}

/* ── 3b. One-time spend: flag decides bank vs capital ─────────────────────
   Same ₹9,000 sofa twice. Paid from business cash (init_invest=0) it leaves
   the bank; flagged initial investment (init_invest=1) it is outside capital
   and the bank is untouched. Neither moves netPnL — One-time is never opex.
     init 0: bank = 10,000 − 9,000 = 1,000 · netPnL 10,000
     init 1: bank = 10,000           · netPnL 10,000                          */
{
  bn = 1; en = 1;
  const B = block([bk({ date: '2026-10-02', prop: '685, Sector 45, Ggn', net: 10000 })]);
  const own = computeCash(B, block([ex({ txn: '', month: '2026-10-01', item: 'Sofa', prop: '685, Sector 45, Ggn', amt: 9000, type: 'One-time', init: 0 })]), 'All', null);
  en = 1;
  const cap = computeCash(B, block([ex({ txn: '', month: '2026-10-01', item: 'Sofa', prop: '685, Sector 45, Ggn', amt: 9000, type: 'One-time', init: 1 })]), 'All', null);
  eq('one-time from business cash reduces the bank', own.bank, 1000);
  eq('one-time from business cash leaves netPnL alone', own.netPnL, 10000);
  eq('one-time with a blank txn date lands on its expense month in the day curve', own.dayMap['2026-10-01'], -9000);
  eq('one-time flagged initial investment stays out of the bank', cap.bank, 10000);
  eq('flagged one-time is not counted as oneTime', cap.oneTime, 0);
}

/* ── 4. LATENT: a booking with no Booking ID vanishes from every cash figure ─
   computeCash line 388 `if (!c || !c[18]) return;`. Production count today:
   0 rows (SELECT COUNT(*) ... WHERE booking_id IS NULL OR TRIM(booking_id)='' → 0),
   so this is latent, not live — but the Worker's own KPI (index.js totalRev)
   applies no such filter, so the very first ID-less row makes the server's
   Total Revenue and the client's Bank Balance disagree by that row's net.
   Here: adding a ₹5,000 ID-less booking must move totalNet to 25,000.        */
{
  const { E } = fixture();
  bn = 1;
  const B = block([
    bk({ date: '2026-05-10', prop: 'Spira 3028', net: 10000 }),
    bk({ id: '', date: '2026-05-12', prop: 'Spira 3028', net: 5000 }),
  ]);
  const c = computeCash(B, E, 'All', null);
  eq('an ID-less booking is still money earned', c.totalNet, 15000);
}

/* ── 5. LATENT: a negative pending inflates "Received" above what was earned ─
   `pending` counts only pend > 0 (line 392) but `recv` subtracts pend
   unconditionally (line 393). A −1,000 pending (overpayment / refund owed)
   on a ₹5,000 booking gives recv = 5,000 − (−1,000) = 6,000: the month claims
   to have received more cash than the booking ever generated, while `bank`
   stays on the 5,000 basis. Production today: 0 rows with pending < 0.       */
{
  bn = 1;
  const B = block([bk({ date: '2026-05-10', prop: 'Spira 3028', net: 5000, pend: -1000 })]);
  const c = computeCash(B, block([]), 'All', null);
  eq('negative pending — bank basis', c.bank, 5000);
  eq('recv must not exceed the net it came from', c.monthly[0].recv, 5000);
}

/* ── 6. Exiting a saving books both legs on their real days ───────────────
   One ₹3,000 FD dated 2026-05-15, nothing else.
     Active                         → 05-15: −3,000                 bank −3,000
     Matured 2026-08-15, recv 3,200 → 05-15: −3,000 · 08-15: +3,200 bank +200
     Withdrawn at a loss, recv 2,700 → bank −300 (the loss)
     Exited before exit_date existed → both legs on 05-15, net +200   */
{
  sn = 1;
  const active = computeCash(block([]), block([]), 'All',
    block([sv({ date: '2026-05-15', amt: 3000, status: 'Active' })]));
  sn = 1;
  const matured = computeCash(block([]), block([]), 'All',
    block([sv({ date: '2026-05-15', amt: 3000, status: 'Matured', ret: 3200, exit: '2026-08-15' })]));
  sn = 1;
  const loss = computeCash(block([]), block([]), 'All',
    block([sv({ date: '2026-05-15', amt: 3000, status: 'Withdrawn', ret: 2700, exit: '2026-07-01', scheme: 'Mutual Funds', platform: 'Groww' })]));
  sn = 1;
  const legacy = computeCash(block([]), block([]), 'All',
    block([sv({ date: '2026-05-15', amt: 3000, status: 'Matured', ret: 3200 })]));
  eq('Active saving books the outflow on its date', active.dayMap['2026-05-15'], -3000);
  eq('Active saving is out of the bank', active.bank, -3000);
  eq('exited saving keeps the outflow on the investment date', matured.dayMap['2026-05-15'], -3000);
  eq('exited saving credits the total received on the exit date', matured.dayMap['2026-08-15'], 3200);
  eq('exited saving: bank moves by the gain only', matured.bank, 200);
  eq('withdrawn at a loss: bank carries the loss', loss.bank, -300);
  eq('day curve still ends on the bank', Object.values(matured.dayMap).reduce((a, v) => a + v, 0), matured.bank);
  eq('no exit date → both legs on the investment day', legacy.dayMap['2026-05-15'], 200);
  const sv2 = computeSavings(block([sv({ date: '2026-05-15', amt: 3000, status: 'Withdrawn', ret: 2700, exit: '2026-07-01' })]));
  eq('computeSavings: gain/loss is received − amount', sv2.returnsRealized, -300);
  eq('computeSavings: received back is the total', sv2.receivedBack, 2700);
  eq('computeSavings: exit date carried on the entry', sv2.entries[0].exitDate, '2026-07-01');
}

/* ── 7. FINDING: savings status matching is case/whitespace exact ──────────
   computeSavings line 349 and computeCash line 425 both compare
   `String(c[4] || '') === 'Active'`, while ciRepeat/ciInitInvest in the same
   file trim + lowercase. A row saved as 'active' or 'Active ' is counted in
   `counts.total` but lands in NO branch: it is neither invested nor realized,
   so ₹5,000 of real principal is simply absent from the Invested card and from
   the bank balance. Production status values are clean today ('Active' only),
   so this is latent — but nothing in the data path enforces it.             */
{
  sn = 1;
  const S = block([sv({ date: '2026-05-15', amt: 5000, status: 'active' })]);
  const s = computeSavings(S);
  eq('lower-case status — counted in total', s.counts.total, 1);
  eq('"active" is Active: ₹5,000 must be invested', s.invested, 5000);

  const c = computeCash(block([]), block([]), 'All', S);
  eq('a lower-case Active saving must still reduce the bank', c.bank, -5000);
}

/* ── 8. computeSavings arithmetic on the well-formed fixture ───────────────
   S1 ₹3,000 Active → invested 3,000, byScheme.FD = {c:1, amt:3000}
   S2 ₹1,000 Matured, received ₹1,200 → returnsRealized 200, NOT in invested
   counts: active 1, matured 1, withdrawn 0, total 2                          */
{
  const { S } = fixture();
  const s = computeSavings(S);
  eq('savings invested (Active principal only)', s.invested, 3000);
  eq('savings realized returns', s.returnsRealized, 200);
  eq('savings counts', s.counts, { active: 1, matured: 1, withdrawn: 0, total: 2 });
  eq('savings byScheme is Active-only', s.byScheme, { FD: { c: 1, amt: 3000 } });
  eq('savings byPlatform is Active-only', s.byPlatform, { HDFC: { c: 1, amt: 3000 } });
}

/* ── 9. Expenses whose property does not match any booking property ────────
   Production row id 107 has property 'Electricity bill' (the item name landed
   in the property column): ₹1,704, Recurring. It is inside the All view's
   opex and inside NO per-property view, so it widens the same
   Σ(per-property) ≠ All gap as the savings do — by a further ₹1,704.
   Hand check: one ₹1,704 mis-keyed expense, one ₹10,000 booking.
     All        → totalExp 1,704 · netPnL  8,296
     Spira 3028 → totalExp     0 · netPnL 10,000                              */
{
  bn = 1; en = 1;
  const B = block([bk({ date: '2026-05-10', prop: 'Spira 3028', net: 10000 })]);
  const E = block([ex({ txn: '2026-06-05', month: '2026-05-01', item: 'Spira 3028', prop: 'Electricity bill', amt: 1704, type: 'Recurring', init: 0 })]);
  eq('mis-keyed property — All view sees the expense', computeCash(B, E, 'All', null).totalExp, 1704);
  eq('mis-keyed property — property view does not', computeCash(B, E, 'Spira 3028', null).totalExp, 0);
  /* The live instance of this (expense id 107) was corrected at source on
     2026-09-05 and every expense now resolves to a real property. The fixture
     stays because the CODE still behaves this way: an expense filed against a
     name no property has is counted in All and in no property view, with nothing
     to flag it. Kept as the standing description of that gap. */
  eq('a mis-keyed property lands in All but in no property view',
     computeCash(B, E, 'Spira 3028', null).totalExp
     + computeCash(B, E, 'Spira 2212', null).totalExp, 0);
}

console.log(`\n${pass} passed, ${fail} failed`);
failures.forEach((f) => console.log(f));
process.exit(fail ? 1 : 0);
